import Foundation
import Testing
@testable import Contrarreloj

/// The app's formatting, share, mail and keyboard helpers must produce exactly what the web's
/// `app/utils` produce (fixture generated by Tools/parity from the web code).
private struct AppUtilsFixture: Decodable {
    struct Clock: Decodable { let ms: Double; let text: String }
    struct Signed: Decodable { let value: Int; let text: String }
    struct Board: Decodable { let duration: GameDuration; let filter: DifficultyFilter; let category: QuizCategory?; let text: String }
    struct ShareText: Decodable {
        let points: Int; let duration: GameDuration; let filter: DifficultyFilter
        let category: QuizCategory?; let emoji: String; let text: String
    }
    struct ShareURL: Decodable { let category: QuizCategory?; let url: String }
    struct Reason: Decodable { let key: String; let label: String; let subject: String }
    struct Mailto: Decodable { let email: String; let subject: String; let body: String; let href: String }
    struct QuestionReport: Decodable { let email: String; let id: String; let text: String; let href: String }
    struct Key: Decodable {
        struct Action: Decodable { let type: String; let index: Int? }
        let key: String; let optionCount: Int; let action: Action?
    }
    let formatClock: [Clock]
    let formatSeconds: [Clock]
    let formatSigned: [Signed]
    let describeBoard: [Board]
    let shareText: [ShareText]
    let shareUrl: [ShareURL]
    let contactReasons: [Reason]
    let mailtoHref: [Mailto]
    let questionReportHref: [QuestionReport]
    let actionForKey: [Key]
}

struct AppUtilsParityTests {
    private let fixture: AppUtilsFixture

    init() throws {
        fixture = try TestResources.json("app-utils", as: AppUtilsFixture.self)
    }

    @Test func clockAndSecondsAndSignsMatchWeb() {
        for c in fixture.formatClock { #expect(formatClock(ms: c.ms) == c.text, "clock \(c.ms)") }
        for c in fixture.formatSeconds { #expect(formatSeconds(ms: c.ms) == c.text, "seconds \(c.ms)") }
        for c in fixture.formatSigned { #expect(formatSigned(c.value) == c.text, "signed \(c.value)") }
    }

    @Test func boardDescriptionsMatchWeb() {
        #expect(fixture.describeBoard.count == 64)
        for b in fixture.describeBoard {
            #expect(describeBoard(b.duration, b.filter, b.category) == b.text)
        }
    }

    @Test func shareTextAndURLMatchWeb() {
        for s in fixture.shareText {
            let input = ShareInput(points: s.points, duration: s.duration, filter: s.filter, category: s.category, emoji: s.emoji)
            #expect(shareText(input) == s.text)
        }
        for s in fixture.shareUrl {
            #expect(shareURL(category: s.category).absoluteString == s.url)
        }
    }

    @Test func contactReasonsMatchWeb() {
        #expect(ContactReason.allCases.map(\.key) == fixture.contactReasons.map(\.key))
        #expect(ContactReason.allCases.map(\.label) == fixture.contactReasons.map(\.label))
        #expect(ContactReason.allCases.map(\.subject) == fixture.contactReasons.map(\.subject))
    }

    @Test func mailLinksMatchWeb() {
        for m in fixture.mailtoHref {
            #expect(mailtoHref(email: m.email, subject: m.subject, body: m.body) == m.href)
        }
        for q in fixture.questionReportHref {
            #expect(questionReportDraft(id: q.id, text: q.text).mailtoURL.absoluteString == q.href, "\(q.id)")
        }
    }

    @Test func keyboardShortcutsMatchWeb() {
        for k in fixture.actionForKey {
            let expected: GameKeyAction? = switch k.action?.type {
            case "answer": .answer(k.action!.index!)
            case "skip": .skip
            default: nil
            }
            #expect(actionForKey(k.key, optionCount: k.optionCount) == expected, "\(k.key) / \(k.optionCount)")
        }
    }

    @Test func playerReportDraftIncludesBoardAndUid() {
        let draft = playerReportDraft(board: "60_aleatorio", uid: "abc123", name: "Ana")
        #expect(draft.to == "informacion@contrarreloj-quiz.com")
        #expect(draft.body.contains("60_aleatorio"))
        #expect(draft.body.contains("abc123"))
        #expect(draft.body.contains("Ana"))
    }
}
